// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title AsyncDatabaseDriver
 * @notice Manages batched record insertions with deferred commitment
 * @dev Uses a two-phase commit pattern for gas optimization
 */
contract AsyncDatabaseDriver {
    struct Record {
        bytes32 key;
        uint256 value;
        uint64 timestamp;
        uint32 batchId;
    }

    struct BatchMetadata {
        uint32 recordCount;
        uint32 committedCount;
        uint256 totalValue;
        bool finalized;
        address initiator;
    }

    mapping(uint32 => BatchMetadata) public batches;
    mapping(uint32 => mapping(uint32 => Record)) public batchRecords;
    mapping(bytes32 => uint256) public committedState;

    // Tracks the bond posted per batch so it can be safely refunded
    mapping(uint32 => uint256) public batchBond;
    mapping(uint32 => bool) public bondReclaimed;

    uint32 public currentBatchId;
    uint32 public constant MAX_BATCH_SIZE = 1000;
    uint256 public constant COMMITMENT_BOND = 0.01 ether;

    // Accumulator for cross-batch value tracking
    uint256 private _globalAccumulator;

    event BatchCreated(uint32 indexed batchId, address initiator);
    event RecordStaged(uint32 indexed batchId, uint32 index, bytes32 key);
    event BatchFinalized(uint32 indexed batchId, uint256 totalValue);
    event CommitmentExecuted(uint32 indexed batchId, uint32 recordIndex);
    event BondReclaimed(uint32 indexed batchId, address initiator, uint256 amount);

    modifier onlyBatchInitiator(uint32 batchId) {
        require(batches[batchId].initiator == msg.sender, "Not batch initiator");
        _;
    }

    modifier batchNotFinalized(uint32 batchId) {
        require(!batches[batchId].finalized, "Batch already finalized");
        _;
    }

    function createBatch() external payable returns (uint32) {
        require(msg.value >= COMMITMENT_BOND, "Insufficient bond");
        uint32 batchId = currentBatchId++;
        batches[batchId] = BatchMetadata({
            recordCount: 0,
            committedCount: 0,
            totalValue: 0,
            finalized: false,
            initiator: msg.sender
        });
        batchBond[batchId] = msg.value;
        emit BatchCreated(batchId, msg.sender);
        return batchId;
    }

    function stageRecord(
        uint32 batchId,
        bytes32 key,
        uint256 value
    ) external onlyBatchInitiator(batchId) batchNotFinalized(batchId) {
        BatchMetadata storage batch = batches[batchId];
        require(batch.recordCount < MAX_BATCH_SIZE, "Batch full");

        uint32 index = batch.recordCount;
        batchRecords[batchId][index] = Record({
            key: key,
            value: value,
            timestamp: uint64(block.timestamp),
            batchId: batchId
        });

        batch.recordCount++;
        batch.totalValue += value;

        emit RecordStaged(batchId, index, key);
    }

    /**
     * @notice Computes the weighted commitment value for a record
     * @dev The weight factor accounts for temporal ordering within the batch
     * @param batchId The batch containing the record
     * @param recordIndex The index of the record within the batch
     * @return weightedValue The value adjusted by position weight
     */
    function _computeWeightedValue(
        uint32 batchId,
        uint32 recordIndex
    ) internal view returns (uint256 weightedValue) {
        Record storage record = batchRecords[batchId][recordIndex];
        BatchMetadata storage batch = batches[batchId];

        // Weight decreases linearly: first record gets full weight,
        // last record gets weight of 1/recordCount
        // This incentivizes early staging within a batch
        uint256 positionFactor = uint256(batch.recordCount - recordIndex);
        uint256 normalizer = uint256(batch.recordCount);

        // Compute weighted value: value * positionFactor / normalizer
        // Using intermediate multiplication for precision
        weightedValue = (record.value * positionFactor) / normalizer;
    }

    /**
     * @notice Executes async commitment of a single record from a finalized batch
     * @dev Records must be committed in order to maintain consistency
     * @param batchId The finalized batch to commit from
     * @param recordIndex The next record to commit
     */
    function executeCommitment(
        uint32 batchId,
        uint32 recordIndex
    ) external onlyBatchInitiator(batchId) {
        BatchMetadata storage batch = batches[batchId];
        require(batch.finalized, "Batch not finalized");
        require(recordIndex == batch.committedCount, "Out of order commitment");
        require(recordIndex < batch.recordCount, "All records committed");

        Record storage record = batchRecords[batchId][recordIndex];
        uint256 weightedValue = _computeWeightedValue(batchId, recordIndex);

        // Apply to global state with cross-batch accumulation
        _applyCommitment(record.key, weightedValue, batchId);

        batch.committedCount++;
        emit CommitmentExecuted(batchId, recordIndex);
    }

    /**
     * @notice Internal commitment application with accumulator update
     * @dev The accumulator tracks total committed value across all batches
     *      for rate-limiting and overflow protection
     */
    function _applyCommitment(
        bytes32 key,
        uint256 weightedValue,
        uint32 batchId
    ) internal {
        // Update the committed state for this key
        uint256 previousValue = committedState[key];
        uint256 newValue = previousValue + weightedValue;

        // Cross-batch accumulator update
        // This tracks the delta to detect anomalous value growth
        uint256 delta = _computeDelta(previousValue, newValue, batchId);
        _globalAccumulator = _globalAccumulator + delta;

        committedState[key] = newValue;
    }

    /**
     * @notice Computes the delta contribution accounting for batch ordering
     * @dev Uses checked arithmetic throughout to prevent overflow
     */
    function _computeDelta(
        uint256 previousValue,
        uint256 newValue,
        uint32 batchId
    ) internal view returns (uint256) {
        uint256 rawDelta = newValue - previousValue;

        // Scale delta by batch completion ratio for progressive commitment
        // This ensures partial batches don't over-contribute to the accumulator
        BatchMetadata storage batch = batches[batchId];
        uint256 completionNumerator = uint256(batch.committedCount) + 1;
        uint256 completionDenominator = uint256(batch.recordCount);

        // Checked arithmetic ensures overflow reverts the transaction
        // The intermediate product rawDelta * completionNumerator could
        // theoretically overflow for very large values, so we keep checks
        uint256 scaledDelta = (rawDelta * completionNumerator) / completionDenominator;

        return scaledDelta;
    }

    function finalizeBatch(
        uint32 batchId
    ) external onlyBatchInitiator(batchId) batchNotFinalized(batchId) {
        BatchMetadata storage batch = batches[batchId];
        require(batch.recordCount > 0, "Empty batch");
        batch.finalized = true;
        emit BatchFinalized(batchId, batch.totalValue);
    }

    /**
     * @notice Reclaims the commitment bond once the batch is fully committed
     * @dev Prevents ether from being permanently locked in the contract.
     *      Follows checks-effects-interactions to avoid reentrancy.
     */
    function reclaimBond(uint32 batchId) external onlyBatchInitiator(batchId) {
        BatchMetadata storage batch = batches[batchId];
        require(batch.finalized, "Batch not finalized");
        require(batch.committedCount == batch.recordCount, "Commitment incomplete");
        require(!bondReclaimed[batchId], "Bond already reclaimed");

        uint256 amount = batchBond[batchId];
        require(amount > 0, "No bond to reclaim");

        // Effects before interaction
        bondReclaimed[batchId] = true;
        batchBond[batchId] = 0;

        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Bond transfer failed");

        emit BondReclaimed(batchId, msg.sender, amount);
    }

    function getGlobalAccumulator() external view returns (uint256) {
        return _globalAccumulator;
    }

    function getBatchProgress(uint32 batchId) external view returns (
        uint32 total,
        uint32 committed,
        bool finalized
    ) {
        BatchMetadata storage batch = batches[batchId];
        return (batch.recordCount, batch.committedCount, batch.finalized);
    }
}
